import { strict as assert } from "node:assert";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { getBounds, NodeIO } from "@gltf-transform/core";

// Reuse the repository's simplified J20 asset generated by
// scripts/generate-moving-target-lods.mjs. This demo copy preserves its mesh,
// materials, and existing node rotation, while centering it on the target's
// position and giving it a useful size in meters. The source stays unchanged.
// Run from any directory: node scripts/generate-lod-demo-model.mjs
const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = resolve(repositoryRoot, "public/model/lod/j20-lod.glb");
const outputPath = resolve(
  repositoryRoot,
  "public/model/lod-demo-aircraft.glb",
);
const maximumHorizontalSize = 120;
const io = new NodeIO();
const document = await io.read(sourcePath);
const scenes = document.getRoot().listScenes();
assert.equal(scenes.length, 1, "The source aircraft must have one scene.");

const scene = scenes[0];
// getBounds accounts for the original nodes' world transforms. The asset is
// glTF Y-up, so its horizontal axes are X and Z; Cesium handles Y-up conversion.
const sourceBounds = getBounds(scene);
const sourceSize = sourceBounds.max.map(
  (maximum, axis) => maximum - sourceBounds.min[axis],
);
assert.ok(sourceSize.every((size) => Number.isFinite(size) && size > 0));
const scale = maximumHorizontalSize / Math.max(sourceSize[0], sourceSize[2]);
const sourceCenter = sourceBounds.min.map(
  (minimum, axis) => (minimum + sourceBounds.max[axis]) / 2,
);
const root = document
  .createNode("LOD demo: centered Y-up aircraft, 120 m horizontal extent")
  .setScale([scale, scale, scale])
  .setTranslation(sourceCenter.map((coordinate) => -coordinate * scale));

for (const child of scene.listChildren()) {
  scene.removeChild(child);
  root.addChild(child);
}
scene.addChild(root);

const bounds = getBounds(scene);
for (let axis = 0; axis < 3; axis += 1) {
  assert.ok(
    Math.abs(bounds.min[axis] + bounds.max[axis]) < 1e-6,
    "The resulting bounds must be centered on the origin.",
  );
}
const size = bounds.max.map((maximum, axis) => maximum - bounds.min[axis]);
assert.ok(Math.abs(Math.max(size[0], size[2]) - maximumHorizontalSize) < 1e-6);
await io.write(outputPath, document);

// Re-read the GLB so the reported bounds also verify the serialized result.
const outputDocument = await io.read(outputPath);
const outputBounds = getBounds(outputDocument.getRoot().listScenes()[0]);
console.log(
  JSON.stringify(
    { sourcePath, outputPath, sourceBounds, bounds: outputBounds, size },
    null,
    2,
  ),
);
